"use client";
/* Polly, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Polly(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("polly"); }, []);
  return React.createElement("piix-pal", { "pal": "polly", ...piixAttrs(props) });
}

export default Polly;
